@START
@OUTPUT "Ustani i spremi krevet"
@OUTPUT "Operi zube i umij se"
@OUTPUT "Obuci školsku odjeću"
@OUTPUT "Doručkuj"
@OUTPUT "Uzmi školsku torbu i kreni"
@END

@START
@OUTPUT "Otvori aplikaciju Gmail"
@OUTPUT "Klikni na dugme 'Nova poruka' (+)"
@INPUT primalac_email
@INPUT naslov_poruke
@INPUT tekst_poruke
@OUTPUT "Klikni na dugme 'Pošalji' (Send)"
@END

@START
@INPUT a, b
@CALC zbir = a + b
@CALC razlika = a - b
@OUTPUT "Zbir je", zbir
@OUTPUT "Razlika je", razlika
@END

@START
@INPUT a, b
@CALC obim = 2 * (a + b)
@CALC povrsina = a * b
@OUTPUT "Obim =", obim
@OUTPUT "Površina =", povrsina
@END

@START
@INPUT a
@CALC O = {{4}} * a
@CALC P = a * {{a}}
@OUTPUT O
{{@OUTPUT}} P
@END

@START
@INPUT m
@CALC cm = m * 100
@CALC mm = m * 1000
@OUTPUT m, "m =", cm, "cm =", mm, "mm"
@END

@START
@OUTPUT "Unesi udaljenost na karti u centimetrima:"
{{@INPUT}} cm_na_karti
@CALC km_u_prirodi = cm_na_karti * {{1}}
@OUTPUT km_u_prirodi
@END

@START
@INPUT kolicina, cijena, dostava
@CALC roba = kolicina * cijena
@CALC ukupno = roba + dostava
@OUTPUT "Za platiti:", ukupno
@END

@START
@INPUT o1, o2, o3
@CALC prosjek = {{(o1 + o2 + o3)}} / 3
@OUTPUT "Prosjek je", prosjek
@END

@START
@INPUT cijena, popust
@CALC iznos = cijena * popust / 100
@CALC nova = cijena - iznos
@OUTPUT "Popust iznosi", iznos
@OUTPUT "Nova cijena je", nova
@END

@START
@INPUT sedmicno, sedmica, cijena
@CALC usteda = sedmicno * sedmica
@CALC ostatak = usteda - cijena
@OUTPUT "Uštedio si", usteda, "KM"
@OUTPUT "Nakon kupovine ostaje", ostatak, "KM"
@END

@START
@INPUT n
@CALC jedinice = n % 10
@CALC desetice = int(n / 10)
@CALC zbir = jedinice + desetice
@OUTPUT "Desetice:", desetice, "jedinice:", jedinice
@OUTPUT "Zbir cifara:", zbir
@END

@START
@INPUT ukupno
@CALC sati = {{int}}(ukupno / 60)
@CALC minuta = ukupno {{%}} 60
@OUTPUT ukupno, "minuta =", sati, "h i", minuta, "min"
@END

@START
@INPUT a, b
@OUTPUT "Prije zamjene:", a, b
@SET pomocna = a
@SET a = b
@SET b = pomocna
@OUTPUT "Poslije zamjene:", a, b
@END
